#!/usr/bin/env python3
"""Week 3 · harness for Task 3. Do not edit this file.

Synthetic documents with near-duplicates planted in them, so the ground truth
is known and everybody's numbers are comparable. No download needed.

    documents  2,000 shingle sets
    planted    120 near-duplicate pairs above the threshold
    scored     calls to similarity() - the comparisons you actually made
    checked    recall against the true pairs, computed by brute force once

    python3 bench.py
    python3 bench.py --yours
"""
import argparse, random, time

SEED, N_DOCS, SHINGLES, PLANTED, THRESHOLD = 246, 2_000, 60, 120, 0.6
VOCAB = 5_000


def build(seed=SEED):
    rng = random.Random(seed)
    docs = [set(rng.sample(range(VOCAB), SHINGLES)) for _ in range(N_DOCS)]
    # plant near-duplicates: copy a document and change a few shingles
    for _ in range(PLANTED):
        i = rng.randrange(N_DOCS)
        clone = set(docs[i])
        for _ in range(rng.randint(4, 14)):
            clone.discard(rng.choice(list(clone)))
            clone.add(rng.randrange(VOCAB))
        docs.append(clone)
    rng.shuffle(docs)
    return docs


class Counter:
    def __init__(self):
        self.calls = 0

    def __call__(self, a, b):
        self.calls += 1
        u = a | b
        return len(a & b) / len(u) if u else 0.0


def truth(docs):
    """Every truly similar pair, found once, not charged to anybody."""
    out = set()
    for i in range(len(docs)):
        di = docs[i]
        for j in range(i + 1, len(docs)):
            dj = docs[j]
            u = len(di | dj)
            if u and len(di & dj) / u >= THRESHOLD:
                out.add((i, j))
    return out


def run(cls, label, docs, true_pairs):
    sim = Counter()
    t0 = time.perf_counter()
    found = cls(THRESHOLD).find(docs, sim)
    elapsed = time.perf_counter() - t0

    found = {(min(p), max(p)) for p in found}
    hit = len(found & true_pairs)
    recall = hit / len(true_pairs) if true_pairs else 1.0
    precision = hit / len(found) if found else 1.0
    print(f"  {label:<12} comparisons {sim.calls:>10,}   recall {recall:>6.1%}   "
          f"precision {precision:>6.1%}   {elapsed:>6.2f}s")
    return {"calls": sim.calls, "recall": recall, "precision": precision}


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--yours", action="store_true")
    a = p.parse_args()

    docs = build()
    print(f"\n  {len(docs):,} documents, threshold {THRESHOLD}")
    true_pairs = truth(docs)
    print(f"  {len(true_pairs)} truly similar pairs\n")

    from task3_scale import BruteForce
    base = run(BruteForce, "baseline", docs, true_pairs)

    if a.yours:
        from task3_scale import YourFinder
        mine = run(YourFinder, "yours", docs, true_pairs)
        print()
        if mine["recall"] < 0.90:
            print(f"   FAIL  recall {mine['recall']:.1%} - you are missing real "
                  f"pairs. Fewer comparisons does not count yet.")
        else:
            cut = 1 - mine["calls"] / base["calls"]
            print(f"   ok    recall {mine['recall']:.1%}")
            print(f"   comparisons avoided  {cut:.2%}  "
                  f"({mine['calls']:,} instead of {base['calls']:,})")
            grade = ("strong" if cut >= 0.99 and mine["recall"] >= 0.95 else
                     "good" if cut >= 0.95 else
                     "pass" if cut > 0.50 else "not yet")
            print(f"\n   -> {grade}")
    print()


if __name__ == "__main__":
    main()
